/* NOVA Academy adult demo. Runs fully offline after first load (the optional Google font falls back to system fonts).
   No student sign-in, persistent personal data, microphone capture, payment or API calls.
*/
(() => {
'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=(k,fallback)=>{try{const v=localStorage.getItem('nova_demo_'+k);return v===null?fallback:JSON.parse(v)}catch{return fallback}};
const save=(k,v)=>{try{localStorage.setItem('nova_demo_'+k,JSON.stringify(v))}catch{}};
const S={page:'overview',grade:3,lessonId:'animal',step:0,paused:false,autoPlay:false,speaking:false,muted:true,answer:null,answers:{},choices:{},feedback:'',demoFinished:load('finished',false),stats:load('stats',{lessons:0,quizzes:0,correct:0,attempts:0}),studio:'art',studioSubject:'dragon',studioScene:'forest',studioColor:'purple',studioName:'Moonlight Creature',studioStory:{hero:'Nori the fox',place:'a magical forest',goal:'save a river',problem:'a broken water pump',ending:'the friends fixed it together'},studioDraw:false,studioAnimationPlaying:true,gameScore:0,gameRound:0,gameOver:false,gameFeedback:'',curriculumSearch:'',curriculumModule:0,selectedStudent:'s1',teacherTab:'overview',adminTab:'classes',authoringId:'hello',drafts:load('drafts',{}),view:'all',fullscreen:false,selectedVoice:null,quizAnswers:{}};
let toastTimer,autoTimer,modelFrame,modelDrag=false,modelYaw=.65,modelPitch=.2,modelScale=1,drawCanvasMouse=false;
const viewNames={overview:'Overview',classroom:'Live classroom',curriculum:'Curriculum',studios:'Creative studios',teacher:'Teacher console',students:'Student portfolio',parents:'Parent portal',admin:'School admin',authoring:'Lesson authoring',trust:'Trust & readiness'};
const lesson=()=>SAMPLE_LESSONS.find(l=>l.id===S.lessonId)||SAMPLE_LESSONS[0];
const step=()=>lesson().steps[S.step]||lesson().steps[0];
const button=(label,action,kind='outline',extra='')=>`<button class="btn btn-${kind}" data-action="${esc(action)}" ${extra}>${label}</button>`;
const pill=(text,type='blue')=>`<span class="pill pill-${type}">${text}</span>`;
const footer=()=>`<p class="footer-note">NOVA Academy is a concept demonstration for adult educators and school decision-makers. All schools, student names, activities and performance data are fictional. Guided visuals and narration are prepared; no live OpenAI API, third-party generation, payment processing or child accounts are active.</p>`;
const pageHeader=(eyebrow,title,description,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${actions}</div>`;
const robot=(state='idle')=>`<div class="robot ${esc(state)}" aria-label="Original animated NOVA robot, ${esc(state)}"><div class="antenna"></div><div class="head"><div class="face"><i class="eye left"></i><i class="eye right"></i><i class="mouth"></i></div></div><i class="arm left"></i><i class="arm right"></i><div class="body"></div><i class="foot left"></i><i class="foot right"></i></div>`;
const avatar=(person)=>`<span class="avatar" style="background:${esc(person.avatar)};color:${esc(person.color)}">${esc(person.initials)}</span>`;
function toast(msg){let n=$('#toast');n.textContent=msg;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3400)}
function modal(title,body,actions=''){const el=$('#modal');el.innerHTML=`<div class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row between"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div><div>${body}</div><div class="dialog-actions">${actions||button('Close','close-modal','outline')}</div></div>`;el.classList.add('open')}
function closeModal(){$('#modal').innerHTML='';$('#modal').classList.remove('open')}
function setPage(page){if(!viewNames[page])return;clearTimeout(autoTimer);stopVoice();S.page=page;if(page!=='classroom')S.autoPlay=false;S.fullscreen=false;document.body.classList.remove('projector-mode');$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===page));$('#sidebar').classList.remove('open');$('#crumb').textContent=viewNames[page];render();window.scrollTo({top:0,behavior:'instant'})}
function render(){clearTimeout(autoTimer);const renderers={overview,curriculum,classroom,studios,teacher,students,parents,admin,authoring,trust};$('#main').innerHTML=renderers[S.page]();attachVisuals();scheduleAuto()}
function goClassroom(id='animal'){if(id==='animal'){window.location.href='live-classroom.html';return;}S.autoPlay=false;S.lessonId=id;S.step=0;S.answer=null;S.answers={};S.choices={};S.feedback='';S.quizAnswers={};S.paused=false;setPage('classroom')}
function updateSummary(){save('stats',S.stats);save('finished',S.demoFinished)}
function stopVoice(){if('speechSynthesis'in window)try{speechSynthesis.cancel()}catch{};S.speaking=false}
function speak(){const cur=step();if(!('speechSynthesis'in window)){toast('Speech is unsupported in this browser; captions remain available.');return}stopVoice();if(S.muted)return;const u=new SpeechSynthesisUtterance(cur.say||cur.body||'');u.rate=S.grade<=2?.85:.94;u.pitch=1.08;u.onstart=()=>{S.speaking=true;const r=$('.stage-robot .robot');if(r)r.classList.add('speaking')};u.onend=()=>{S.speaking=false;const r=$('.stage-robot .robot');if(r)r.classList.remove('speaking')};u.onerror=()=>{S.speaking=false};speechSynthesis.speak(u)}
function stepTo(next){if(next<0||next>=lesson().steps.length)return;clearTimeout(autoTimer);stopVoice();S.step=next;S.answer=null;S.feedback='';S.quizAnswers={};S.paused=false;render();if(!S.muted){speak()}}
function completeLesson(){S.autoPlay=false;clearTimeout(autoTimer);S.demoFinished=true;S.stats.lessons++;updateSummary();toast('Sample lesson complete! Fictional reporting views updated.');setPage('teacher')}
function overview(){return `
 <section class="hero"><div class="hero-copy"><div class="hero-kicker">✳ THE FUTURE OF CREATIVE LEARNING</div><h1>Every child has a universe of <em>ideas.</em></h1><p>Meet NOVA, the friendly animated AI classroom guide helping teachers turn curiosity into discovery, creation and critical thinking.</p><div class="hero-actions">${button('▶ &nbsp; Experience a live classroom','launch-flagship','teal')}${button('Explore the curriculum  ↗','go-curriculum','white')}${button('Request school walkthrough','open-enquiry','outline','style="background:transparent;color:#e9fffa;border-color:#ffffff6b"')}</div><p class="tiny" style="margin-top:17px;opacity:.74">Interactive school sales demo · Fictional records · Ages / provider eligibility review required for production</p></div><div class="hero-robot"><div class="orbit"></div><div class="floating-token token1">✦</div><div class="floating-token token2">💡</div><div class="floating-token token3">▦</div>${robot('happy')}</div></section>
 <div class="grid grid4 mt24"><div class="card stat-card"><span class="stat-icon ic-teal">▣</span><strong>8</strong><small>Grades in the learning pathway</small></div><div class="card stat-card"><span class="stat-icon ic-violet">▤</span><strong>128</strong><small>Weekly curriculum outlines</small></div><div class="card stat-card"><span class="stat-icon ic-blue">✦</span><strong>7</strong><small>Interactive creative studios</small></div><div class="card stat-card"><span class="stat-icon ic-amber">◇</span><strong>9</strong><small>Authored sample demo lessons</small></div></div>
 <div class="row between mt24" style="margin-bottom:17px"><div><div class="eyebrow">LEARNING BY DOING</div><h2 class="section-title">Explore the possibilities</h2><p class="section-subtitle">Designed for school owners to experience, not just read about.</p></div><span class="pill pill-purple">Adult presentation mode</span></div>
 <div class="grid grid3"><div class="card feature-card card-link" data-action="launch-flagship"><div class="feature-icon">🤖</div><h3>Interactive AI teacher</h3><p>An expressive animated robot, synchronized browser narration and teacher-led lessons.</p><div class="feature-footer">Try the classroom →</div></div><div class="card feature-card card-link" data-action="go-studios"><div class="feature-icon">🎨</div><h3>Creative AI studios</h3><p>Build imaginary creatures, books, 3D scenes and mini-games with guided choices.</p><div class="feature-footer">Explore studios →</div></div><div class="card feature-card card-link" data-action="go-teacher"><div class="feature-icon">📊</div><h3>Real learning visibility</h3><p>See portfolio evidence, rubric-based learning reports and the teacher control center.</p><div class="feature-footer">View reporting →</div></div></div>
 <div class="content-strip"><div class="card featured-lesson"><div class="featured-visual">🐉</div><div style="flex:1"><div class="eyebrow">FLAGSHIP SAMPLE LESSON · CLASS 3</div><h3 style="font-size:17px;margin:10px 0 7px">Create an imaginary animal with AI</h3><p class="muted small">Watch students imagine, describe, inspect and improve a creative idea in a guided 12-scene lesson.</p><div class="overview-steps"><span class="step-mini">Imagine</span><span class="step-mini">Describe</span><span class="step-mini">Create</span><span class="step-mini">Evaluate</span><span class="step-mini">Improve</span></div><div class="mt16">${button('Start sample lesson →','launch-flagship','primary','')}</div></div></div><div class="card p24"><div class="row between"><h3>Three pillars of learning</h3>${pill('Curriculum model','teal')}</div><div class="timeline mt16"><div class="timeline-item"><span class="timeline-dot">1</span><div><b>Understand AI</b><small>Patterns, examples, limitations and responsibility.</small></div></div><div class="timeline-item"><span class="timeline-dot">2</span><div><b>Create with AI</b><small>Ideas, storytelling, visuals and useful projects.</small></div></div><div class="timeline-item"><span class="timeline-dot">3</span><div><b>Explore your potential</b><small>Teacher-observed interests and evidence of improvement.</small></div></div></div></div></div>${footer()}`}
function curriculum(){const lessons=(window.CURRICULUM||[]).filter(l=>l.grade===S.grade && (!S.curriculumModule||l.module===S.curriculumModule) && (!S.curriculumSearch||[l.title,l.description].join(' ').toLowerCase().includes(S.curriculumSearch.toLowerCase())));return `${pageHeader('THE LEARNING JOURNEY','Explore the curriculum','128 developmentally appropriate weekly outlines across Classes 1–8.',pill('16 weeks × 8 grades','purple'))}<div class="card p24"><div class="row between" style="flex-wrap:wrap;gap:18px"><div><h3>Choose a grade</h3><p class="small muted mb0">Each grade has its own age-appropriate progression.</p></div><div class="grade-tabs">${Array.from({length:8},(_,i)=>`<button class="grade-tab ${S.grade===i+1?'active':''}" data-action="grade" data-grade="${i+1}">Class ${i+1}</button>`).join('')}</div></div><div class="divider"></div><div class="filters"><input class="search-input" aria-label="Search lessons" id="curriculumSearch" placeholder="Search lessons..." value="${esc(S.curriculumSearch)}"><button class="grade-tab ${S.curriculumModule===0?'active':''}" data-action="module" data-module="0">All modules</button>${['Discover AI','Create with AI','Real-world exploration','Become an innovator'].map((m,i)=>`<button class="grade-tab ${S.curriculumModule===i+1?'active':''}" data-action="module" data-module="${i+1}">${m}</button>`).join('')}</div></div><div class="lesson-grid">${lessons.map(l=>{const sample=SAMPLE_LESSONS.find(x=>x.grade===l.grade&&x.week===l.week);return `<div class="lesson-tile"><div class="row between"><span class="module-label">WEEK ${String(l.week).padStart(2,'0')}</span>${sample?pill('Interactive demo','teal'):pill('Outline','gray')}</div><h3>${esc(l.title)}</h3><p>${esc(l.description)}</p><div class="row between"><span class="tiny muted">${l.durationMinutes} minutes</span>${sample?`<button class="btn btn-sm btn-primary" data-action="load-lesson" data-id="${sample.id}">▶ Try</button>`:`<button class="btn btn-sm btn-outline" data-action="lesson-detail" data-id="${l.id}">Details ↗</button>`}</div></div>`}).join('')||'<p>No lessons match this filter. Try a different search.</p>'}</div><div class="callout warning mt24"><b>Curriculum readiness:</b> Eight interactive sample lessons are authored for the sales demo. The other 120 weekly items are structured outlines and still require complete instructional authoring, educator review and classroom testing before they can be sold as a finished course.</div>${footer()}`}
function stageBody(cur){const key=`${S.lessonId}_${S.step}`;let html='';if(cur.type==='question'){html=`<div class="lesson-options">${cur.options.map((opt,i)=>{const ans=S.answers[key];return `<button class="option ${ans===i?'selected '+(i===cur.answer?'good':'bad'):''}" data-action="answer" data-index="${i}">${esc(opt)}</button>`}).join('')}</div>${S.answers[key]!==undefined?`<div class="stage-feedback">${S.answers[key]===cur.answer?'✓ Correct! Explain your reasoning to the teacher.':'Think again: '+esc(cur.hint||'Check the question carefully.')} ${S.answers[key]!==cur.answer?'<button class="btn btn-sm btn-white" data-action="retry-question">Try again</button>':''}</div>`:''}`}
else if(cur.type==='choice'){html=`<div class="lesson-options">${cur.options.map((opt,i)=>`<button class="option ${S.choices[key]===i?'selected good':''}" data-action="choose" data-index="${i}">${esc(opt)}</button>`).join('')}</div>${S.choices[key]!==undefined?`<div class="stage-feedback">Great choice. Let's explain why you chose: ${esc(cur.options[S.choices[key]])}.</div>`:''}`}
else if(cur.type==='quiz'){html=`<div style="display:grid;gap:15px;max-width:660px">${cur.questions.map((q,j)=>{const answer=S.answers[key+'_'+j];return `<div><div style="font-size:12px;font-weight:800;margin-bottom:7px">${j+1}. ${esc(q.q)}</div><div class="lesson-options">${q.a.map((a,i)=>`<button class="option ${answer===i?(i===q.correct?'good':'bad'):''}" style="font-size:11px;padding:9px 13px" data-action="answer-quiz" data-q="${j}" data-index="${i}">${esc(a)}</button>`).join('')}</div></div>`}).join('')}</div>${cur.questions.every((_,j)=>S.answers[key+'_'+j]!==undefined)?`<div class="stage-feedback">Your result: ${cur.questions.filter((q,j)=>S.answers[key+'_'+j]===q.correct).length} / ${cur.questions.length} · ${cur.questions.every((q,j)=>S.answers[key+'_'+j]===q.correct)?'Strong understanding!':'Review your answers with the teacher.'}</div>`:''}`}
else if(cur.type==='visual'||cur.type==='portfolio'){html=`<div class="visual-creative"><div class="animal-preview" aria-label="Prepared concept illustration">${esc(cur.emoji||'✨')}<small>Prepared illustration</small></div><div class="stage-info"><strong>Teacher-guided example</strong><br>Notice the details, ask questions,<br>and describe what you would change.<br><br>${pill('Pre-rendered visual','purple')}</div></div>`}
else if(cur.type==='model'){html=`<div style="max-width:520px"><canvas class="model-canvas" data-model="lesson" aria-label="Drag to rotate the prepared three dimensional creature" height="320" width="520"></canvas><div class="row">${button('− Zoom out','zoom-out','white','style="min-height:31px;padding:5px 10px"')}${button('+ Zoom in','zoom-in','white','style="min-height:31px;padding:5px 10px"')}<span class="tiny" style="color:#bdd6e4">Drag to rotate</span></div></div>`}
else{html=`<div class="visual-creative" style="margin-top:22px"><div style="width:110px;height:110px;background:#ffffff18;border:1px solid #ffffff33;display:grid;place-items:center;border-radius:25px;font-size:61px">${esc(cur.emoji||'✦')}</div><div style="max-width:260px;font-size:12px;color:#c9dfed;line-height:1.7">${esc(cur.type==='summary'?'Think · Test · Improve · Explain':cur.type==='reflect'?'Share your thinking. Your voice matters.':'Human imagination leads. AI is a tool.')}</div></div>`}
return html}
function classroom(){let l=lesson(),cur=step(),pct=(S.step+1)/l.steps.length*100;return `${pageHeader('IMMERSIVE CLASSROOM','Meet NOVA, your AI teacher','A teacher-controlled, fully interactive example of the proposed classroom system.',`<div class="row">${pill('Adult simulation','teal')}<select class="select" id="lessonSelect" aria-label="Select sample lesson" style="max-width:230px">${SAMPLE_LESSONS.map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>Class ${x.grade} · ${esc(x.title)}</option>`).join('')}</select></div>`)}
<div class="classroom-shell"><div class="classroom-top"><div class="row"><span style="font-size:21px;color:var(--teal)">✳</span><div><strong>CLASS ${l.grade} &nbsp; / &nbsp; ${esc(l.title)}</strong><div style="font-size:10px;opacity:.55;margin-top:3px">NOVA TEACHING EXPERIENCE · SYNTHETIC PARTICIPANTS</div></div></div><div class="row"><span style="font-size:10px">STEP ${String(S.step+1).padStart(2,'0')} / ${l.steps.length}</span><button class="btn btn-sm btn-white" data-action="projector">${S.fullscreen?'↙ Exit projector':'⛶ Projector view'}</button></div></div>
<div class="classroom-stage"><div class="stage-content"><div class="stage-kicker">${esc(cur.type.toUpperCase())} · ${esc(l.objective.split('.')[0])}</div><h2 class="stage-title">${esc(cur.title)}</h2><p class="stage-desc">${esc(cur.body)}</p>${stageBody(cur)}<div class="hint-note mt16"><b>NOVA says:</b> “${esc(cur.say)}”</div></div><div class="stage-robot">${robot(S.speaking?'speaking':(cur.type==='question'||cur.type==='quiz'?'thinking':S.paused?'idle':'happy'))}</div></div>
<div class="classroom-bottom"><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}" aria-label="Lesson progress"><div style="width:${pct}%"></div></div><div class="control-bar"><div class="control-group">${button('← Previous','previous','outline',S.step===0?'disabled':'')}${S.step===l.steps.length-1?button('✓ Finish lesson','finish','primary'):button('Next step →','next','primary')}${button(S.paused?'▶ Resume':'Ⅱ Pause','pause','outline')}${button(S.autoPlay?'Ⅱ Stop auto-demo':'▶ Auto-demo','auto-demo','outline')}${button('↻ Replay narration','narrate','outline')}</div><div class="control-group"><span class="controls-note">${S.muted?'Browser narration off':'Browser narration on'}</span>${button(S.muted?'🔇 Enable voice':'🔊 Mute','toggle-voice','outline')}${button('⏹ Stop','stop-lesson','outline')}</div></div></div></div>
<div class="teacher-strip"><div class="teacher-control"><span class="emoji">🎛️</span><div>Teacher in control<small>Pause, resume and override</small></div></div><div class="teacher-control"><span class="emoji">🎤</span><div>Microphone off<small>No audio is captured in this demo</small></div></div><div class="teacher-control"><span class="emoji">✓</span><div>Objective marking<small>Rule-based sample scoring</small></div></div><div class="teacher-control"><span class="emoji">🛟</span><div>Offline lesson mode<small>No API connection required</small></div></div></div><div class="below-classroom mt24"><div class="grid grid2"><div class="card p24"><div class="row between"><h3>Teacher participation console</h3>${pill('Simulated','purple')}</div><p class="small muted">Choose a fictional student and demonstrate how group and individual participation would be different.</p><div class="row" style="flex-wrap:wrap"><select class="select" id="participantSelect" style="max-width:230px" aria-label="Select fictional demo student">${FICTIONAL_STUDENTS.map(s=>`<option value="${s.id}" ${S.selectedStudent===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>${button('Call on student','call-student','primary')}${button('Whole class vote','class-vote','outline')}</div></div><div class="card p24"><div class="row between"><h3>Instructional safeguards</h3>${pill('Adult demo only','amber')}</div><p class="small muted">The lesson is state-driven. Questions, scoring, navigation and model actions are constrained by teacher-approved lesson steps. No unrestricted AI can direct the class.</p><div class="steps-visual"><span>Teacher override</span><span>Deterministic quizzes</span><span>Offline fallback</span><span>Voice default OFF</span></div></div></div></div>${footer()}`}
function dashboardKPI(label,value,emoji,col,note){return `<div class="card stat-card"><span class="stat-icon ic-${col}">${emoji}</span><strong>${value}</strong><small>${esc(label)}</small>${note?`<div class="tiny muted mt8">${esc(note)}</div>`:''}</div>`}
function teacher(){let lessonRows=SAMPLE_LESSONS.slice(0,5);let tb=S.teacherTab;return `${pageHeader('TEACHER WORKSPACE','Good morning, Ms. Morgan','Manage classroom learning without needing to become a software expert.',button('▶ Start today’s lesson','launch-flagship','primary'))}<div class="grid grid4">${dashboardKPI('Total enrolled (fictional)','24','♙','teal','Grade 3A')}${dashboardKPI('Completed sample sessions',String(12+S.stats.lessons),'✓','violet','Illustrative class activity')}${dashboardKPI('Class course progress','69%','▤','blue','Fictional baseline')}${dashboardKPI('Projects in review','6','✎','amber','Prepared demo records')}</div><div class="grade-tabs mt24" style="margin-bottom:20px">${[['overview','Overview'],['console','Live teaching'],['assess','Assessment review'],['schedule','Lesson preparation']].map(([id,name])=>`<button class="grade-tab ${tb===id?'active':''}" data-action="teacher-tab" data-id="${id}">${name}</button>`).join('')}</div>
${tb==='overview'?`<div class="grid grid2"><div class="card p28"><div class="row between"><h3>Today’s teaching plan</h3>${pill('Class 3A','blue')}</div><div class="timeline mt16">${lessonRows.slice(0,3).map((l,i)=>`<div class="timeline-item"><span class="timeline-dot">${i+1}</span><div><b>${esc(l.title)}</b><small>Class ${l.grade} · ${l.duration} minutes · ${i===0?'Ready for presentation':'Ready to preview'}</small><button class="btn btn-sm btn-outline mt8" data-action="load-lesson" data-id="${l.id}">Preview lesson →</button></div></div>`).join('')}</div></div><div class="card p28"><div class="row between"><h3>Class competency snapshots</h3>${pill('Fictional data','purple')}</div>${[['Responsible AI use',87],['Creative briefing',78],['Evidence checking',67],['Improving work',74]].map(([n,v])=>`<div class="metric-row"><span>${n}</span><div class="row"><div class="metric-meter"><span style="width:${v}%"></span></div><b>${v}%</b></div></div>`).join('')}<p class="tiny muted mt16">Illustrative competencies based on fictional teacher-reviewed rubrics. No intelligence scoring.</p></div></div>`:''}
${tb==='console'?`<div class="grid grid2"><div class="card p28"><h3>Teaching control center</h3><p class="muted small">All sensitive controls are disabled or simulated. Projector lessons and structured quizzes are fully functional.</p><div class="grid grid2"><div class="task-entry">✓ Ready: Approved lesson steps</div><div class="task-entry">✓ Ready: Browser narration</div><div class="task-entry">✓ Ready: Quiz grading</div><div class="task-entry">✕ Mic: Off in demo</div></div><div class="mt24">${button('Launch projected classroom','launch-flagship','primary')}</div></div><div class="card p28"><h3>Manual fallback</h3><p class="small muted">If voice or an external AI service fails, advance the prepared lesson, run offline quizzes and read the captions aloud.</p>${button('Demonstrate manual mode','manual-mode','outline')}<div class="callout mt16">For school deployment, the teacher can intervene, reject feedback and end a session immediately.</div></div></div>`:''}
${tb==='assess'?`<div class="card p28"><div class="row between"><h3>Teacher-reviewed work</h3>${pill('Illustrative assessment records','purple')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Recent work</th><th>Rubric status</th><th>Actions</th></tr></thead><tbody>${FICTIONAL_STUDENTS.map((x,i)=>`<tr><td><div class="row">${avatar(x)}<strong>${esc(x.name)}</strong></div></td><td>${esc(x.project)}</td><td>${pill(i%2?'Needs feedback':'Reviewed',i%2?'amber':'teal')}</td><td><button class="btn btn-sm btn-outline" data-action="student-select" data-id="${x.id}">Review →</button></td></tr>`).join('')}</tbody></table></div><p class="tiny muted">AI subjective scores are advisory in the proposed production system; teacher approval is always required.</p></div>`:''}
${tb==='schedule'?`<div class="grid grid2"><div class="card p28"><h3>Lesson readiness checklist</h3>${['Smartboard or projector ready','Approved content loaded','Captions visible','Audio tested with teacher permission','Safety expectations reviewed','Printable backup activity available'].map((t,i)=>`<label class="task-entry" style="margin-bottom:10px"><input type="checkbox" ${i<=2?'checked':''}>${esc(t)}</label>`).join('')}</div><div class="card p28"><h3>Recommended next lesson</h3>${pill('Class 3 · Week 5','blue')}<h2 style="margin-top:14px">Create an Imaginary Animal</h2><p class="small muted">40 minute instructional plan with short conversations, guided creation, a prepared 3D viewer and a two-question exit ticket.</p>${button('Preview complete lesson','launch-flagship','primary')}</div></div>`:''}${footer()}`}
function students(){const st=FICTIONAL_STUDENTS.find(s=>s.id===S.selectedStudent)||FICTIONAL_STUDENTS[0];return `${pageHeader('STUDENT WORKSPACE','Creative portfolios','Beautiful, evidence-led learning records. All students below are fictional.',pill('No real student accounts','purple'))}<div class="card p24 mb12"><div class="row between" style="flex-wrap:wrap"><div class="row">${avatar(st)}<div><h3 style="margin:0">${esc(st.name)}</h3><small class="muted">Fictional student · Class 3A</small></div></div><select class="select" id="studentSelect" aria-label="Choose fictional student" style="max-width:230px">${FICTIONAL_STUDENTS.map(s=>`<option value="${s.id}" ${s.id===st.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div></div><div class="grid grid3 mt16">${dashboardKPI('Lessons completed',String(st.lessons+(S.demoFinished?1:0)),'▤','teal')}${dashboardKPI('Sample assessment result',st.score+'%','☑','blue','Fictional teacher-reviewed baseline')}${dashboardKPI('Improvement since last review','+'+st.growth+'%','↗','violet','Illustrative, not predictive')}</div><div class="grid grid2 mt24"><div class="card p28"><div class="row between"><h3>Recent creative portfolio</h3>${pill('Student choices visible','teal')}</div><div class="project-card"><div class="project-img">${st.id==='s1'?'🐉':st.id==='s2'?'💧':st.id==='s3'?'🦊':st.id==='s4'?'🏡':'🌊'}</div><div class="project-body"><h3>${esc(st.project)}</h3><p>Original idea, guided creation and revision history.</p><div class="row">${pill('Teacher reviewed','teal')}${pill('Fictional example','purple')}</div></div></div>${button('View project evidence','project-evidence','outline','style="margin-top:14px"')}</div><div class="card p28"><h3>Learning observations</h3><div class="timeline mt16"><div class="timeline-item"><span class="timeline-dot">✦</span><div><b>Emerging interest: ${esc(st.interest)}</b><small>From activity selection, not an AI personality judgment.</small></div></div><div class="timeline-item"><span class="timeline-dot">✓</span><div><b>Teacher observation</b><small>${esc(st.note)}</small></div></div><div class="timeline-item"><span class="timeline-dot">↗</span><div><b>Suggested next activity</b><small>Choose another guided creation task and compare revisions.</small></div></div></div><div class="callout mt24">No hidden talent prediction, psychological labels or automated career recommendations.</div></div></div>${footer()}`}
function parents(){const st=FICTIONAL_STUDENTS.find(s=>s.id===S.selectedStudent)||FICTIONAL_STUDENTS[0];return `${pageHeader('PARENT EXPERIENCE','A clearer picture of progress','A plain-language preview of a fictional child’s creative learning.',button('⎙ Print sample report','print-report','outline'))}<div class="callout mb12">All records are fictional. The proposed parent portal would require verified guardian authorization, role-based security and an approved school deployment.</div><div class="grid grid2 mt16"><div class="card p28"><div class="row between"><div><span class="eyebrow">PARENT LEARNING SNAPSHOT</span><h2 style="margin:12px 0 5px">Look what Maya created!</h2><p class="small muted">A week of imagining, learning and improving.</p></div><span style="font-size:62px">🐉</span></div><div class="divider"></div><h3>What did my child learn?</h3><p class="small muted">Maya practiced describing creative ideas with clear details, compared her draft to her original request, and decided which parts to improve.</p>${[['Clear instructions',88],['Evaluating results',79],['Explaining choices',84]].map(([a,v])=>`<div style="margin:15px 0"><div class="row between tiny bold" style="margin-bottom:7px"><span>${a}</span><span>${v}%</span></div><div class="horizontal-progress"><span style="width:${v}%"></span></div></div>`).join('')}</div><div class="card p28"><h3>What did my child create?</h3><div class="project-card"><div class="project-img">🐉</div><div class="project-body"><h3>The Moonlight Dragon</h3><p>A prepared fictional portfolio example showing an initial idea, an AI-assisted concept illustration and an improved creative brief.</p>${pill('Creative storytelling','purple')}</div></div><div class="timeline mt16"><div class="timeline-item"><span class="timeline-dot">✓</span><div><b>Teacher-reviewed observation</b><small>Maya identified a mismatch in her concept and suggested a revision.</small></div></div><div class="timeline-item"><span class="timeline-dot">✦</span><div><b>Try at home</b><small>Ask your child to explain how they would improve a drawing without using any AI tool.</small></div></div></div></div></div>
<div class="print-report mt24" id="report"><div class="row between"><div><div class="eyebrow">FUTURE HORIZONS ACADEMY</div><h2 style="margin:10px 0 2px">Learning progress report</h2><p class="small muted">Fictional parent report · Grade 3A · Demo term</p></div>${pill('Illustrative, not real','purple')}</div><div class="divider"></div><div class="grid grid3">${dashboardKPI('Sample lessons',String(11+(S.demoFinished?1:0)),'▤','teal')}${dashboardKPI('Reviewed projects',4,'◇','violet')}${dashboardKPI('Responsible-use practice','Growing','♥','blue')}</div><div class="mt24"><h3>Teacher comment</h3><p class="small">“Maya shows persistence when improving illustrations. She can now explain why checking an AI-generated result matters.”</p></div><p class="tiny muted">Educational observations are based on fictional teacher-reviewed evidence. They are not intelligence, personality or career assessments.</p></div>${footer()}`}
function admin(){const tab=S.adminTab;return `${pageHeader('MULTI-SCHOOL MANAGEMENT','School administration','A preview of school operations, permissions and service readiness.',pill('Fictional institution','purple'))}<div class="grid grid4">${dashboardKPI('Active demo classes','4','▦','teal')}${dashboardKPI('Synthetic students','93','♙','blue')}${dashboardKPI('Assigned educators','4','◫','violet')}${dashboardKPI('Live API requests','0','⚡','amber','No external AI services active')}</div><div class="grade-tabs mt24" style="margin-bottom:20px">${[['classes','Classes'],['teachers','Teachers'],['permissions','Access & privacy'],['billing','Plans & usage']].map(([id,n])=>`<button class="grade-tab ${id===tab?'active':''}" data-action="admin-tab" data-id="${id}">${n}</button>`).join('')}</div>
${tab==='classes'?`<div class="card p28"><div class="row between"><h3>Classes at Future Horizons Academy</h3>${pill('Demo roster only','purple')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Class</th><th>Teacher</th><th>Students</th><th>Course progress</th><th>Course</th></tr></thead><tbody>${FICTIONAL_CLASSES.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.teacher)}</td><td>${c.students}</td><td><div class="row"><div class="metric-meter"><span style="width:${c.progress}%"></span></div><b>${c.progress}%</b></div></td><td>AI ${c.grade<=2?'Explorers':c.grade<=5?'Creators':'Innovators'}</td></tr>`).join('')}</tbody></table></div></div>`:''}
${tab==='teachers'?`<div class="card p28"><h3>Faculty allocation</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Assigned teacher</th><th>Class</th><th>Training status</th><th>Safety setting</th></tr></thead><tbody>${FICTIONAL_CLASSES.map(c=>`<tr><td>${esc(c.teacher)}</td><td><b>${esc(c.name)}</b></td><td>${pill('Demo ready','teal')}</td><td>Teacher controls required</td></tr>`).join('')}</tbody></table></div></div>`:''}
${tab==='permissions'?`<div class="grid grid2"><div class="card p28"><h3>Role-based access design</h3><div class="alert-list">${[['Platform owner','Organization configuration and system oversight'],['School administrator','Access to authorized school-wide settings'],['Teacher','Only their assigned classes and approved curriculum'],['Parent / guardian','Only an authorized child’s approved reports'],['Student','Age-dependent restricted classroom workspace']].map(([a,b])=>`<div class="alert-item"><span>⬡</span><div><b>${a}</b><small>${b}</small></div></div>`).join('')}</div></div><div class="card p28"><h3>Production security gates</h3><p class="small muted">This demo has no accounts or backend. The production system must implement these controls on servers and at the database layer.</p>${['School tenant isolation','Authenticated session and RBAC checks','Guardian authorization where required','Encrypted storage and role-scoped queries','Audit logging and incident handling','Child-data provider eligibility and retention review'].map(t=>`<div class="metric-row"><span>${t}</span>${pill('Not implemented','amber')}</div>`).join('')}</div></div>`:''}
${tab==='billing'?`<div class="grid grid2"><div class="card p28"><h3>Illustrative standard school license</h3>${pill('Pricing not set','gray')}<p class="small muted mt16">A proposed package could include prepared classroom lessons, group quizzes, teacher controls, limited creation demonstrations and reporting.</p><div class="metric-row"><span>Live model spend</span><b>Not enabled</b></div><div class="metric-row"><span>Payment processing</span><b>Not enabled</b></div><div class="metric-row"><span>Seat pricing</span><b>To be validated</b></div></div><div class="card p28"><h3>Future cost controls</h3>${['Cached prepared lesson audio','Approved resource reuse','Per-school AI usage quotas','Optional premium generation limits','Per-provider cost accounting','Failure fallback to prepared content'].map(t=>`<div class="metric-row"><span>${t}</span>${pill('Planned','blue')}</div>`).join('')}</div></div>`:''}${footer()}`}
function authoring(){const l=SAMPLE_LESSONS.find(x=>x.id===S.authoringId)||SAMPLE_LESSONS[0],draft=S.drafts[l.id]||{};return `${pageHeader('EDUCATOR WORKFLOW','Curriculum authoring studio','Edit a local demonstration draft, review and approve before publishing.',pill('Local demo state only','purple'))}<div class="grid grid2"><div class="card p28"><h3>Lesson editor</h3><p class="small muted">A small working prototype of curriculum content management. Changes are saved only in this browser and do not affect real students.</p><div class="studio-fieldset"><label class="field">Choose sample lesson<select id="authoringSelect">${SAMPLE_LESSONS.map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>Class ${x.grade}: ${esc(x.title)}</option>`).join('')}</select></label><label class="field">Title<input id="editTitle" maxlength="130" value="${esc(draft.title??l.title)}"></label><label class="field">Learning objective<textarea id="editObjective" maxlength="600">${esc(draft.objective??l.objective)}</textarea></label><label class="field">Teacher instruction<textarea id="editNotes" maxlength="600">${esc(draft.notes??'Teacher controls each step. Ask a question before showing the prepared answer. Review all subjective feedback.')}</textarea></label><div class="row" style="flex-wrap:wrap">${button('Save draft','save-draft','primary')}${button('Submit for review','submit-review','outline')}${button('Approve lesson','approve-lesson','outline')}</div></div></div><div class="card p28"><div class="row between"><h3>Version & approval workflow</h3>${pill((draft.status||'Published sample').toUpperCase(),draft.status==='Approved'?'teal':'amber')}</div><div class="timeline mt16"><div class="timeline-item"><span class="timeline-dot">1</span><div><b>Draft</b><small>Editable text and educator-authored lesson logic.</small></div></div><div class="timeline-item"><span class="timeline-dot">2</span><div><b>Review</b><small>Content, correctness, age-appropriateness and safety need formal oversight in production.</small></div></div><div class="timeline-item"><span class="timeline-dot">3</span><div><b>Approved</b><small>Teacher-approved version may be prepared for publication.</small></div></div><div class="timeline-item"><span class="timeline-dot">4</span><div><b>Published</b><small>This step is simulated. Demo content is never deployed to students.</small></div></div></div><div class="divider"></div><h3>Local version history</h3><p class="small muted">${draft.editedAt?'Last updated: '+esc(new Date(draft.editedAt).toLocaleString()):'No local edits yet. Starting from pre-authored sample content.'}</p><div class="callout warning">Production needs immutable lesson versions, an independent educator reviewer, authorized approval rights and rollback controls. This prototype does not pretend to enforce server-side authorization.</div></div></div>${footer()}`}
function trust(){const done=[['Original animated robot','CSS/SVG-style vector character with behavior states'],['Prepared lesson narration','Built-in browser speech, initiated by an adult'],['Teacher lesson controls','Pause, resume, advance, stop and offline mode'],['Nine sample lesson flows','Approved static scripts with usable interaction'],['128-item curriculum catalog','Titles, goals and implementation metadata'],['Rule-based assessment','Real client-side scoring and feedback'],['Creative demos','Local illustrative output and interactive controls'],['3D viewer','Prepared local mesh rendered with custom canvas projection'],['Portfolio and reporting','Entirely synthetic demonstration data']];const pending=[['Real OpenAI Responses / voice','Backend, configured keys, moderation and appropriate child safeguards required'],['Real image and 3D generation','Requires approved external service and budget controls'],['User login, guardian verification','Not built; production backend and enrollment approval required'],['Student data storage','Requires tenant isolation, security and retention enforcement'],['Course authoring approval','Needs server-side workflow, versioning and audit trails'],['Full 128 production lessons','120 are outlines awaiting authoring and teacher review'],['Live public hosting','Site publishing must occur through an authorized host workflow'],['Privacy/legal approval','Jurisdictional child-data and school policy review required']];return `${pageHeader('TRANSPARENCY & TRUST','Built to show, not to overclaim','Every capability is labeled so school decision-makers can separate a demonstration from a deployed service.',pill('Child production: NOT READY','amber'))}<div class="grid grid2"><div class="card p28"><div class="row between"><h3>Working now</h3>${pill('Demo functional','teal')}</div><div class="alert-list">${done.map(([a,b])=>`<div class="alert-item"><span style="color:#27a68e">✓</span><div><b>${a}</b><small>${b}</small></div></div>`).join('')}</div></div><div class="card p28"><div class="row between"><h3>Not activated / requires implementation</h3>${pill('Not production ready','amber')}</div><div class="alert-list">${pending.map(([a,b])=>`<div class="alert-item"><span style="color:#c59a4c">○</span><div><b>${a}</b><small>${b}</small></div></div>`).join('')}</div></div></div><div class="card p28 mt24"><h3>Non-negotiable safety principles</h3><div class="grid grid3 mt16">${[['👩‍🏫','Teachers in control','No uncontrolled AI lesson advancement or unreviewed educational grades.'],['🔒','Data minimization','No child names, voices, images or recordings enter this adult demo.'],['🧠','Evidence, not labels','No intelligence, personality, emotion or hidden-potential predictions.'],['🛡️','Consent and provider review','Underage personal data requires safeguards, permissions and model eligibility checks.'],['📴','Reliable fallback','Prepared lessons and quizzes work without an AI connection.'],['🔍','Human verification','AI-assisted content must be accurate, appropriate and educator approved.']].map(([e,h,p])=>`<div><span style="font-size:24px">${e}</span><h4 style="font-size:13px;margin:10px 0 5px">${h}</h4><p class="tiny muted">${p}</p></div>`).join('')}</div></div>${footer()}`}
function studios(){const tabs=[['art','🎨 Art studio'],['storybook','📖 Storybook'],['3d','🧊 3D creator'],['animation','🎞 Animation'],['learning','🧠 Learning helper'],['inventor','💡 Inventor lab'],['game','🎮 Game lab']];return `${pageHeader('CREATE WITH CURIOSITY','The imagination labs','Guided creation without an unrestricted prompt box. Live AI generation is deliberately not connected.',pill('Prepared, local demonstrations','purple'))}<div class="studio-list">${tabs.map(([id,t])=>`<button class="studio-tab ${S.studio===id?'active':''}" data-action="studio-tab" data-id="${id}">${t}</button>`).join('')}</div>${studioContent()}${footer()}`}
function studioContent(){if(S.studio==='art')return `<div class="studio-layout"><div class="card studio-workspace"><div class="eyebrow">ART & IMAGINATION</div><h2 class="section-title">Build a creative brief</h2><p class="small muted">Choose your ingredients. The result is composed locally from prepared visual assets, not generated by AI.</p><div class="studio-fieldset"><label class="field">Name your creation<input id="artName" maxlength="40" value="${esc(S.studioName)}"></label><label class="field">Main subject</label><div class="chip-list">${[['dragon','🐉 Dragon'],['fox','🦊 Fox'],['robot','🤖 Robot'],['unicorn','🦄 Unicorn']].map(([id,t])=>`<button class="chip ${S.studioSubject===id?'chosen':''}" data-action="art-subject" data-id="${id}">${t}</button>`).join('')}</div><label class="field">Scene</label><div class="chip-list">${[['forest','🌳 Forest'],['space','🌌 Space'],['sunset','🌅 Sunset']].map(([id,t])=>`<button class="chip ${S.studioScene===id?'chosen':''}" data-action="art-scene" data-id="${id}">${t}</button>`).join('')}</div><label class="field">Creative color</label><div class="chip-list">${['purple','teal','gold'].map(c=>`<button class="chip ${S.studioColor===c?'chosen':''}" data-action="art-color" data-id="${c}">${c}</button>`).join('')}</div>${button('✦ Refresh local illustration','art-create','primary')}<p class="tiny muted mb0">The visual responds to your selections. For real AI images, a separate secure provider adapter would be required.</p></div></div><div class="card p24"><div class="studio-preview" style="min-height:550px"><div class="art-output ${esc(S.studioScene)}"><span class="art-orb" style="filter:drop-shadow(0 15px 6px #192f3c29) ${S.studioColor==='teal'?'hue-rotate(85deg)':S.studioColor==='gold'?'hue-rotate(-50deg)':'none'}">${{dragon:'🐉',fox:'🦊',robot:'🤖',unicorn:'🦄'}[S.studioSubject]}</span><div class="art-name">${esc(S.studioName||'My Creation')} · ${esc(S.studioScene)}</div></div><div class="preview-caption">PREPARED ART DEMONSTRATION · NOT AI GENERATED</div></div></div></div>`;
if(S.studio==='storybook'){const p=S.studioStory;return `<div class="studio-layout"><div class="card studio-workspace"><div class="eyebrow">WRITE WITH PURPOSE</div><h2 class="section-title">An original story</h2><p class="small muted">Complete five ingredients; then read your editable book preview.</p><div class="studio-fieldset">${[['hero','Main character'],['place','Setting'],['goal','Goal'],['problem','Challenge'],['ending','Ending']].map(([id,label])=>`<label class="field">${label}<input data-story-field="${id}" maxlength="90" value="${esc(p[id])}"></label>`).join('')}${button('↻ Create story preview','story-preview','primary')}${button('⎙ Print the story','print-story','outline')}<p class="tiny muted">The story text is assembled from your inputs using a fixed local template. It is not a generative AI result.</p></div></div><div class="card p24"><div class="studio-preview"><div class="storybook" id="storybookPrint"><div class="eyebrow">MY LITTLE STORYBOOK</div><div class="book-emoji">🦊 🌳 ✨</div><h3>${esc(p.hero)} and the Big Idea</h3><p>Once upon a time, ${esc(p.hero)} lived in ${esc(p.place)}. Their goal was to ${esc(p.goal)}.</p><p>One day, they faced ${esc(p.problem)}. After thinking and talking to friends, they decided that ${esc(p.ending)}.</p><p><b>The lesson:</b> Good ideas become stronger when we think, work together and revise.</p><span class="tiny muted">Your choices shape this prepared story template.</span></div><div class="preview-caption">EDITABLE GUIDED STORY · LOCAL DEMO</div></div></div></div>`}
if(S.studio==='3d')return `<div class="studio-layout"><div class="card studio-workspace"><div class="eyebrow">SPATIAL THINKING</div><h2 class="section-title">Inspect a 3D creature</h2><p class="small muted">Explore the prepared model from different angles with interactive rotation and zoom.</p><div class="alert-list"><div class="alert-item"><span>①</span><div><b>Notice the shapes</b><small>Observe the three-dimensional head, body and wings.</small></div></div><div class="alert-item"><span>②</span><div><b>Rotate the model</b><small>Click and drag to view it from the side and back.</small></div></div><div class="alert-item"><span>③</span><div><b>Reflect on your choices</b><small>What would you improve? Describe your next design change.</small></div></div></div><div class="row mt24">${button('− Zoom out','zoom-out','outline')}${button('+ Zoom in','zoom-in','primary')}</div><p class="tiny muted mt16">Custom local mesh renderer. Actual text-to-3D generation and GLB import are future integrations.</p></div><div class="card p24"><div class="studio-preview"><div><canvas class="model-canvas" data-model="studio" width="650" height="400" aria-label="Interactive 3D character viewer, drag to rotate"></canvas><div class="tiny muted">DRAG TO ROTATE · USE ZOOM BUTTONS</div></div><div class="preview-caption">PREPARED 3D DEMONSTRATION</div></div></div></div>`;
if(S.studio==='animation')return `<div class="studio-layout"><div class="card studio-workspace"><div class="eyebrow">VISUAL STORYTELLING</div><h2 class="section-title">Animate a little world</h2><p class="small muted">Plan an animated scene, then see a real motion preview built with browser animation.</p><div class="studio-fieldset"><label class="field">Story scene<select id="animationScene"><option value="field">A dragon visits the field</option><option value="moon">A spaceship flies to the moon</option><option value="ocean">A fish explores the ocean</option></select></label><label class="field">Storyboard summary<textarea id="storyboardSummary">Our character travels through a beautiful world, finds a challenge, and tries to solve it.</textarea></label><div class="steps-visual"><span>1. Idea</span><span>2. Storyboard</span><span>3. Motion</span><span>4. Review</span></div>${button(S.studioAnimationPlaying?'Ⅱ Pause animation':'▶ Play animation','toggle-animation','primary')}${button('Review storyboard','review-storyboard','outline')}<p class="tiny muted">Prepared HTML/CSS animation. Generative video is not active.</p></div></div><div class="card p24"><div class="studio-preview"><div class="animated-scene ${S.studioAnimationPlaying?'':'paused'}"><div class="cloud">☁️ ☁️</div><div class="walker">${S.animationScene==='moon'?'🚀':S.animationScene==='ocean'?'🐠':'🐉'}</div></div><div class="preview-caption">PLAYABLE PREPARED ANIMATION · NO AI GENERATION</div></div></div></div>`;
if(S.studio==='learning')return `<div class="studio-layout"><div class="card studio-workspace"><div class="eyebrow">UNDERSTAND MORE</div><h2 class="section-title">Learn, don't copy</h2><p class="small muted">Choose a classroom concept. The lesson helper provides a prepared explanation and a thinking question.</p><div class="chip-list">${[['rain','Why does it rain?'],['plants','How do plants grow?'],['shadows','Why do shadows change?']].map(([id,t])=>`<button class="chip ${S.helperTopic===id?'chosen':''}" data-action="helper-topic" data-id="${id}">${t}</button>`).join('')}</div><div class="callout mt24">The future live assistant will ask guiding questions, not solve a child’s homework for them.</div></div><div class="card p24"><div class="studio-preview"><div class="storybook"><div class="eyebrow">PREPARED LEARNING EXPLANATION</div><h3>${S.helperTopic==='plants'?'How plants grow':S.helperTopic==='shadows'?'Why shadows change':'Why rain falls'}</h3><div class="book-emoji">${S.helperTopic==='plants'?'🌱':S.helperTopic==='shadows'?'☀️':'🌧️'}</div><p>${S.helperTopic==='plants'?'Plants take in water, light and air to grow. Different plants need different conditions.':S.helperTopic==='shadows'?'Light travels in straight paths. When an object blocks light, a shadow appears.':'Water evaporates, cools in the air, and can become tiny droplets in clouds. When droplets grow heavy enough, they fall as rain.'}</p><p><b>Think for yourself:</b> ${S.helperTopic==='plants'?'How would you test whether two plants need the same amount of light?':S.helperTopic==='shadows'?'How could you change a shadow without moving the object?':'Why might rain be more likely when clouds are thick and dark?'}</p></div><div class="preview-caption">FIXED TEACHER-REVIEWED CONTENT</div></div></div></div>`;
if(S.studio==='inventor')return `<div class="studio-layout"><div class="card studio-workspace"><div class="eyebrow">DESIGN THINKING</div><h2 class="section-title">Invent a solution</h2><p class="small muted">Start with a problem, then draw your own first idea on the whiteboard.</p><div class="studio-fieldset"><label class="field">What problem would you solve?<input id="inventProblem" maxlength="110" value="${esc(S.inventProblem||'Plastic waste in our classroom')}"></label><label class="field">Who would benefit?<input id="inventUser" maxlength="80" value="${esc(S.inventUser||'Students and school staff')}"></label><label class="field">What is one real-world constraint?<input id="inventConstraint" maxlength="90" value="${esc(S.inventConstraint||'It must be inexpensive and safe')}"></label><div class="row">${button('Clear drawing','clear-drawing','outline')}${button('Save sketch PNG','save-drawing','primary')}</div><p class="tiny muted">Drawing works locally. No content is uploaded or shared.</p></div></div><div class="card p24"><div class="studio-preview" style="display:block;min-height:480px;text-align:left"><div class="row between"><h3>Invention sketchboard</h3>${pill('Local drawing','teal')}</div><canvas id="drawCanvas" class="sketch-canvas" width="850" height="470" aria-label="Draw your invention with mouse or touch"></canvas><div class="callout mt16"><b>Next step:</b> Explain what your design does, who it helps, and how you would test it.</div></div></div></div>`;
if(S.studio==='game')return `<div class="studio-layout"><div class="card studio-workspace"><div class="eyebrow">GAME DESIGN LAB</div><h2 class="section-title">Pattern match game</h2><p class="small muted">Try a fully playable mini-game. Pick the one symbol that is different from the others. Earn a point for each correct round.</p><div class="card p24" style="box-shadow:none;margin:18px 0"><div class="row between"><div><div class="tiny muted">YOUR POINTS</div><h2 style="font-size:34px;margin:5px 0">${S.gameScore}</h2></div><div><div class="tiny muted">ROUND</div><h2 style="font-size:34px;margin:5px 0">${Math.min(S.gameRound+1,5)} / 5</h2></div></div></div><div class="steps-visual"><span>Notice</span><span>Compare</span><span>Respond</span><span>Reflect</span></div><div class="mt24">${button('↻ Restart challenge','restart-game','primary')}</div></div><div class="card p24"><div class="studio-preview">${S.gameOver?`<div class="mini-game"><div style="font-size:72px">🏆</div><h2>Challenge complete!</h2><p>You earned ${S.gameScore} out of 5 points. Explain how you spotted the pattern.</p>${button('Play again','restart-game','primary')}</div>`:gameBoard()}<div class="preview-caption">REAL PLAYABLE LOCAL MINI-GAME</div></div></div></div>`;
return ''}
function gameBoard(){const icons=[['⭐','⭐','⭐','🌟'],['🔺','🔺','🔷','🔺'],['🍎','🍎','🍊','🍎'],['🐱','🐱','🐱','🐶'],['🟢','🟡','🟢','🟢']];const round=icons[Math.min(S.gameRound,4)],wrong=[3,2,2,3,1][Math.min(S.gameRound,4)];return `<div class="mini-game"><div class="eyebrow" style="justify-content:center">FIND THE DIFFERENT ONE</div><h2>Which does not match?</h2><div style="max-width:375px;display:flex;flex-wrap:wrap;justify-content:center">${round.map((c,i)=>`<button class="game-cell" data-action="game-answer" data-index="${i}" aria-label="Option ${i+1}: ${c}">${c}</button>`).join('')}</div><p class="small muted">${S.gameFeedback||'Tap the odd one out.'}</p></div>`}
function scheduleAuto(){
 clearTimeout(autoTimer);
 if(S.page!=='classroom'||!S.autoPlay||S.paused||S.step>=lesson().steps.length-1)return;
 const cur=step();const key=`${S.lessonId}_${S.step}`;
 let delay=6700;
 if(cur.type==='question'||cur.type==='choice'){
   if(S.answers[key]===undefined&&S.choices[key]===undefined)return;
   delay=2800;
 } else if(cur.type==='quiz'){
   if(!cur.questions.every((_,i)=>S.answers[key+'_'+i]!==undefined))return;
   delay=3500;
 } else if(cur.type==='model')delay=9500;
 else if(cur.type==='visual')delay=8000;
 autoTimer=setTimeout(()=>{if(S.page==='classroom'&&S.autoPlay&&!S.paused)stepTo(S.step+1)},delay);
}
function showLessonDetails(id){const l=(window.CURRICULUM||[]).find(l=>l.id===id);if(!l)return;modal(`Class ${l.grade}, week ${l.week}`,`<div class="eyebrow">MODULE ${l.module}</div><h3>${esc(l.title)}</h3><p>${esc(l.description)}</p><div class="row" style="flex-wrap:wrap">${pill(l.durationMinutes+' min','blue')}${pill('Outline not yet authored','amber')}</div><div class="divider"></div><h3>Planned learning objectives</h3><ul class="small muted">${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Activity sequence</h3><div class="steps-visual">${l.activityPlan.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p class="small muted mt16">${esc(l.teacherNotes)}</p>`,button('Close','close-modal','primary'))}
function drawModel(canvas){const cx=canvas.width/2,cy=canvas.height/2,w=canvas.width,h=canvas.height;const ctx=canvas.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,w,h);const studio=canvas.dataset.model==='studio';let bg=ctx.createRadialGradient(cx,cy,10,cx,cy,330);bg.addColorStop(0,studio?'#f7ffff':'#264f70');bg.addColorStop(1,studio?'#dceaf6':'#0b2949');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);let faces=[];
 const face=(v,color)=>faces.push({v,color});
 function sphere(x,y,z,rx,ry,rz,color,seg=13,rings=9){for(let a=0;a<rings;a++)for(let b=0;b<seg;b++){const p=(ii,jj)=>{const theta=Math.PI*(ii/rings),phi=2*Math.PI*jj/seg;return [x+rx*Math.sin(theta)*Math.cos(phi),y+ry*Math.cos(theta),z+rz*Math.sin(theta)*Math.sin(phi)]};const v0=p(a,b),v1=p(a+1,b),v2=p(a+1,b+1),v3=p(a,b+1);face([v0,v1,v2],color);face([v0,v2,v3],color)}}
 sphere(0,-.3,0,.9,1.04,.64,'#9670d3',15,10);sphere(0,1.04,.24,.78,.78,.68,'#b195e5',15,10);
 // Features on the forward (+Z) side of the prepared creature
 sphere(-.27,1.18,.84,.14,.17,.085,'#213f64',8,6);sphere(.27,1.18,.84,.14,.17,.085,'#213f64',8,6);sphere(-.22,1.24,.915,.045,.055,.028,'#ffffff',8,5);sphere(.32,1.24,.915,.045,.055,.028,'#ffffff',8,5);
 sphere(0,.75,.95,.20,.065,.06,'#e991bd',10,4);sphere(-.57,-.05,.58,.12,.14,.08,'#e4b3e5',8,5);sphere(.57,-.05,.58,.12,.14,.08,'#e4b3e5',8,5);
 sphere(-.48,-1.22,.23,.28,.24,.39,'#b195e5',10,6);sphere(.48,-1.22,.23,.28,.24,.39,'#b195e5',10,6);
 face([[-.8,.1,-.1],[-1.7,.89,-.4],[-1.44,-.44,-.22]],'#5fd6c9');face([[.8,.1,-.1],[1.7,.89,-.4],[1.44,-.44,-.22]],'#5fd6c9');face([[-.7,.4,-.2],[-1.7,.89,-.4],[-1.1,1.0,-.4]],'#ffd280');face([[.7,.4,-.2],[1.7,.89,-.4],[1.1,1.0,-.4]],'#ffd280');
 face([[-.56,1.43,.15],[-.7,2.07,.05],[-.23,1.6,.21]],'#ffd280');face([[.56,1.43,.15],[.7,2.07,.05],[.23,1.6,.21]],'#ffd280');
 const cosY=Math.cos(modelYaw),sinY=Math.sin(modelYaw),cosP=Math.cos(modelPitch),sinP=Math.sin(modelPitch);function rot(v){const [x,y,z]=v;let X=x*cosY+z*sinY,Z=-x*sinY+z*cosY;return [X,y*cosP-Z*sinP,y*sinP+Z*cosP]}
 function project(p){const f=410*modelScale/(5.6-p[2]);return [cx+p[0]*f,cy-p[1]*f]}
 faces=faces.map(f=>{const verts=f.v.map(rot),avg=verts.reduce((s,p)=>s+p[2],0)/3;const a=verts[0],b=verts[1],c=verts[2];const n=[(b[1]-a[1])*(c[2]-a[2])-(b[2]-a[2])*(c[1]-a[1]),(b[2]-a[2])*(c[0]-a[0])-(b[0]-a[0])*(c[2]-a[2]),(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])];const len=Math.hypot(...n)||1;let light=.67+Math.abs((n[0]*-.3+n[1]*.7+n[2]*.7)/len)*.4;return {...f,verts,avg,light}}).sort((a,b)=>a.avg-b.avg);
 const shade=(hex,l)=>{let v=parseInt(hex.slice(1),16),r=(v>>16)&255,g=(v>>8)&255,b=v&255;return `rgb(${Math.min(255,r*l)|0},${Math.min(255,g*l)|0},${Math.min(255,b*l)|0})`};
 // Soft floor shadow
 ctx.fillStyle=studio?'#243c5630':'#00000038';ctx.beginPath();ctx.ellipse(cx,cy+140*modelScale,113*modelScale,18*modelScale,0,0,7);ctx.fill();
 for(let f of faces){const pts=f.verts.map(project);ctx.beginPath();ctx.moveTo(...pts[0]);ctx.lineTo(...pts[1]);ctx.lineTo(...pts[2]);ctx.closePath();ctx.fillStyle=shade(f.color,f.light);ctx.fill()}
 ctx.font='700 12px sans-serif';ctx.fillStyle=studio?'#6a869b':'#d3e8ef';ctx.textAlign='center';ctx.fillText('LOCAL PREPARED 3D MODEL • DRAG TO ROTATE',cx,h-15);
}
function setupModel(){cancelAnimationFrame(modelFrame);const c=$('.model-canvas');if(!c)return;let lastX=0,lastY=0;c.addEventListener('pointerdown',e=>{modelDrag=true;lastX=e.clientX;lastY=e.clientY;c.setPointerCapture(e.pointerId)});c.addEventListener('pointerup',()=>modelDrag=false);c.addEventListener('pointercancel',()=>modelDrag=false);c.addEventListener('pointermove',e=>{if(!modelDrag)return;modelYaw+=(e.clientX-lastX)*.011;modelPitch=Math.max(-.8,Math.min(.8,modelPitch+(e.clientY-lastY)*.009));lastX=e.clientX;lastY=e.clientY});c.addEventListener('wheel',e=>{e.preventDefault();modelScale=Math.max(.65,Math.min(1.5,modelScale+(e.deltaY>0?-.05:.05)))},{passive:false});let old=0;function frame(t){if(!c.isConnected)return;if(t-old>32){if(!modelDrag)modelYaw+=.003;drawModel(c);old=t}modelFrame=requestAnimationFrame(frame)}modelFrame=requestAnimationFrame(frame)}
function setupDrawing(){const c=$('#drawCanvas');if(!c)return;const ctx=c.getContext('2d');ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=5;ctx.strokeStyle='#173861';let drawing=false,last;const pt=e=>{const r=c.getBoundingClientRect();return [(e.clientX-r.left)/r.width*c.width,(e.clientY-r.top)/r.height*c.height]};c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);last=pt(e)});c.addEventListener('pointermove',e=>{if(!drawing)return;const p=pt(e);ctx.beginPath();ctx.moveTo(...last);ctx.lineTo(...p);ctx.stroke();last=p});c.addEventListener('pointerup',()=>drawing=false);c.addEventListener('pointercancel',()=>drawing=false);if(S.savedDrawing){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0);img.src=S.savedDrawing}}
function attachVisuals(){setupModel();setupDrawing()}
function updateQuery(){const inp=$('#curriculumSearch');if(!inp)return;S.curriculumSearch=inp.value;const pos=inp.selectionStart;render();const r=$('#curriculumSearch');if(r){r.focus();try{r.setSelectionRange(pos,pos)}catch{}}}
function handleAction(el){const a=el.dataset.action,id=el.dataset.id,index=Number(el.dataset.index),key=`${S.lessonId}_${S.step}`;switch(a){
 case 'close-modal':closeModal();break;
 case 'go-curriculum':setPage('curriculum');break;
 case 'go-studios':setPage('studios');break;
 case 'go-teacher':setPage('teacher');break;
 case 'open-enquiry':modal('Request a school walkthrough',`<p>This is an adult-only inquiry draft. No details are transmitted to NOVA Academy or stored by this demonstration. Copy the message and share it with the person presenting the product.</p><div class="studio-fieldset"><label class="field">Your name<input id="enquiryName" maxlength="90" autocomplete="name" placeholder="Your name"></label><label class="field">School / organization<input id="enquirySchool" maxlength="120" placeholder="Your school name"></label><label class="field">What would you like to discuss?<textarea id="enquiryMessage" maxlength="500">I would like a guided demonstration of NOVA Academy's AI classroom program for our school.</textarea></label></div>`,button('Cancel','close-modal','outline')+button('Copy enquiry text','copy-enquiry','primary'));break;
 case 'copy-enquiry':{const msg=['NOVA Academy school walkthrough inquiry','Name: '+($('#enquiryName')?.value.trim()||'(not provided)'),'School: '+($('#enquirySchool')?.value.trim()||'(not provided)'),'Message: '+($('#enquiryMessage')?.value.trim()||'(not provided)')].join('\n');const copy=navigator.clipboard?.writeText?.(msg);if(copy&&typeof copy.then==='function'){copy.then(()=>toast('Enquiry copied. Share it with the presenter.')).catch(()=>{modal('Copy your enquiry',`<textarea class="search-input" style="min-height:130px" readonly>${esc(msg)}</textarea><p class="tiny muted">Select and copy manually. No request was sent.</p>`);})}else{modal('Copy your enquiry',`<textarea class="search-input" style="min-height:130px" readonly>${esc(msg)}</textarea><p class="tiny muted">Select and copy manually. No request was sent.</p>`);}break}

 case 'launch-flagship':goClassroom('animal');break;
 case 'load-lesson':goClassroom(id);break;
 case 'grade':S.grade=Number(el.dataset.grade);render();break;
 case 'module':S.curriculumModule=Number(el.dataset.module);render();break;
 case 'lesson-detail':showLessonDetails(id);break;
 case 'next':if(S.step===lesson().steps.length-1){completeLesson()}else stepTo(S.step+1);break;
 case 'previous':stepTo(S.step-1);break;
 case 'finish':completeLesson();break;
 case 'pause':S.paused=!S.paused;stopVoice();render();toast(S.paused?'Teaching paused.':'Teaching resumed.');break;
 case 'auto-demo':S.autoPlay=!S.autoPlay;render();toast(S.autoPlay?'Auto-demo running: pauses at questions until an answer is chosen.':'Automatic progression stopped.');break;
 case 'narrate':S.muted=false;speak();render();break;
 case 'toggle-voice':S.muted=!S.muted;if(S.muted)stopVoice();render();toast(S.muted?'Browser narration muted.':'Browser narration enabled. Press Replay to hear the current explanation.');break;
 case 'stop-lesson':S.autoPlay=false;clearTimeout(autoTimer);stopVoice();modal('End this demo lesson?',`<p>Teacher override: you can stop the lesson at any time and return to the overview. This demo does not record classroom audio.</p>`,button('Cancel','close-modal','outline')+button('End lesson','confirm-stop','primary'));break;
 case 'confirm-stop':closeModal();setPage('overview');break;
 case 'projector':S.fullscreen=!S.fullscreen;document.body.classList.toggle('projector-mode',S.fullscreen);render();break;
 case 'answer':{const cur=step();if(!cur.options||!Number.isInteger(index)||index<0||index>=cur.options.length)return;if(S.answers[key]===undefined){S.stats.attempts++;if(index===cur.answer)S.stats.correct++;S.answers[key]=index;updateSummary()}render();break}
 case 'retry-question':delete S.answers[key];S.feedback='';render();break;
 case 'choose':{const cur=step();if(!cur.options||index<0||index>=cur.options.length)return;S.choices[key]=index;render();break}
 case 'answer-quiz':{let qi=Number(el.dataset.q),cur=step(),q=cur.questions?.[qi];if(!q||index<0||index>=q.a.length)return;const k=key+'_'+qi;if(S.answers[k]===undefined){S.stats.attempts++;if(index===q.correct)S.stats.correct++;if(cur.questions.every((_,j)=>j===qi||S.answers[key+'_'+j]!==undefined))S.stats.quizzes++;S.answers[k]=index;updateSummary()}render();break}
 case 'zoom-in':modelScale=Math.min(1.5,modelScale+.12);const c=$('.model-canvas');if(c)drawModel(c);break;
 case 'zoom-out':modelScale=Math.max(.65,modelScale-.12);const c2=$('.model-canvas');if(c2)drawModel(c2);break;
 case 'call-student':{let st=FICTIONAL_STUDENTS.find(s=>s.id===S.selectedStudent);toast(`Teacher selects fictional student ${st.name}. No individual answer has been recorded.`);break}
 case 'class-vote':modal('Whole class voting',`<p>A teacher can record a group distribution, but the resulting values must never be attributed to individual students.</p><div class="row between"><span class="small">A</span><div class="metric-meter" style="flex:1"><span style="width:60%"></span></div><b>60%</b></div><div class="row between mt8"><span class="small">B</span><div class="metric-meter" style="flex:1"><span style="width:25%"></span></div><b>25%</b></div><div class="row between mt8"><span class="small">C</span><div class="metric-meter" style="flex:1"><span style="width:15%"></span></div><b>15%</b></div><p class="tiny muted mt16">Illustrative group figures, not real collected votes.</p>`);break;
 case 'teacher-tab':S.teacherTab=id;render();break;
 case 'admin-tab':S.adminTab=id;render();break;
 case 'student-select':S.selectedStudent=id;setPage('students');break;
 case 'manual-mode':toast('Manual fallback is the same prepared classroom lesson; teacher controls Next/Previous and subtitles.');goClassroom('animal');break;
 case 'project-evidence':{const st=FICTIONAL_STUDENTS.find(s=>s.id===S.selectedStudent);modal('Fictional project evidence',`<h3>${esc(st.project)}</h3><p><b>Original idea:</b> ${esc(st.interest)} project selected by the fictional student.</p><p><b>Revision:</b> Student compared a prepared AI-assisted sample to the project requirements.</p><p><b>Teacher observation:</b> ${esc(st.note)}</p><div class="callout">All evidence here is an invented demonstration record and cannot substantiate real learning impact.</div>`);break}
 case 'print-report':window.print();break;
 case 'art-subject':S.studioSubject=id;render();break;
 case 'art-scene':S.studioScene=id;render();break;
 case 'art-color':S.studioColor=id;render();break;
 case 'art-create':S.studioName=$('#artName')?.value.trim()||'My Creation';render();toast('Local art preview updated. No AI image API was called.');break;
 case 'studio-tab':S.studio=id;render();break;
 case 'story-preview':$$('[data-story-field]').forEach(f=>S.studioStory[f.dataset.storyField]=f.value.trim()||'an idea');render();toast('Story preview assembled from your own choices.');break;
 case 'print-story':window.print();break;
 case 'toggle-animation':S.studioAnimationPlaying=!S.studioAnimationPlaying;S.animationScene=$('#animationScene')?.value||'field';render();break;
 case 'review-storyboard':modal('Storyboard review',`<div class="steps-visual"><span>Scene 1: introduction</span><span>Scene 2: a challenge</span><span>Scene 3: action</span><span>Scene 4: reflection</span></div><p class="small muted mt16">${esc($('#storyboardSummary')?.value||'A short prepared animation that follows the student-defined story.')}</p><p class="tiny muted">This is a storyboard planning demonstration, not AI video generation.</p>`);break;
 case 'helper-topic':S.helperTopic=id;render();break;
 case 'clear-drawing':{const c=$('#drawCanvas');c.getContext('2d').clearRect(0,0,c.width,c.height);S.savedDrawing=null;toast('Sketch cleared.');break}
 case 'save-drawing':{const c=$('#drawCanvas');const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='nova-invention-sketch.png';a.click();toast('Your local sketch was exported as PNG.');break}
 case 'restart-game':S.gameScore=0;S.gameRound=0;S.gameOver=false;S.gameFeedback='';render();break;
 case 'game-answer':{const ans=[3,2,2,3,1][Math.min(S.gameRound,4)];if(index===ans){S.gameScore++;S.gameFeedback='Great eye! You found the different symbol.'}else S.gameFeedback='Not quite! Compare the shapes in the next round.';S.gameRound++;if(S.gameRound>=5)S.gameOver=true;render();break}
 case 'save-draft':{const l=SAMPLE_LESSONS.find(x=>x.id===S.authoringId);S.drafts[S.authoringId]={title:$('#editTitle').value.trim(),objective:$('#editObjective').value.trim(),notes:$('#editNotes').value.trim(),status:'Draft',editedAt:new Date().toISOString()};save('drafts',S.drafts);render();toast('Local draft saved in this browser.');break}
 case 'submit-review':{const d=S.drafts[S.authoringId];if(!d){toast('Save a draft before review.');break}d.status='Review';d.editedAt=new Date().toISOString();save('drafts',S.drafts);render();toast('Marked for review in local demo. No real reviewer was notified.');break}
 case 'approve-lesson':{const d=S.drafts[S.authoringId];if(!d||d.status!=='Review'){toast('Submit the local draft for review first.');break}d.status='Approved';d.editedAt=new Date().toISOString();save('drafts',S.drafts);render();toast('Marked approved for demo purposes only. Production requires independent authorization.');break}
 default:break}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){if(nav.dataset.page==='classroom'){window.location.href='live-classroom.html';return}setPage(nav.dataset.page);return}const act=e.target.closest('[data-action]');if(act){handleAction(act);return}});
document.addEventListener('change',e=>{const t=e.target;switch(t.id){case 'lessonSelect':goClassroom(t.value);break;case 'participantSelect':S.selectedStudent=t.value;break;case 'studentSelect':S.selectedStudent=t.value;render();break;case 'authoringSelect':S.authoringId=t.value;render();break;case 'animationScene':S.animationScene=t.value;render();break}});
document.addEventListener('input',e=>{if(e.target.id==='curriculumSearch')updateQuery()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal').classList.contains('open'))closeModal();if(S.fullscreen){S.fullscreen=false;document.body.classList.remove('projector-mode');render()}}if(S.page==='classroom'&&['ArrowRight','ArrowLeft'].includes(e.key)&&!['TEXTAREA','INPUT','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();stepTo(S.step+(e.key==='ArrowRight'?1:-1))}});
$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#helpBtn').addEventListener('click',()=>modal('About the NOVA Academy demo',`<p>This is an interactive <b>adult-facing demonstration</b> for school owners, teachers and potential partners.</p><p><b>Working:</b> animated robot, browser narration, structured classroom lessons, quizzes, simulated dashboards, local drawing, mini-game, guided creative previews and prepared 3D model viewer.</p><p><b>Not active:</b> OpenAI API, live microphone, real generation services, authentication, payments or collection of children's information.</p><div class="callout warning">This product is not currently approved or configured for real use by children.</div>`));
window.NOVA_TEST={getState:()=>({...S}),goClassroom,stepTo,render,lessons:SAMPLE_LESSONS};
render();
})();
